  "bridge.moving": "O'CN pasa a ser Ozimut, en ozimut.com: un momento, te llevamos allí con tus ajustes.",
  "moved.title": "O'CN pasa a ser Ozimut",
  "moved.lede": "El sitio se llama ahora <b>Ozimut</b> y está en <b>ozimut.com</b>. Tu cuenta, tus ajustes y tus alertas por correo electrónico se conservan. Algunos pasos útiles, en cada uno de tus dispositivos:",
  "moved.bookmarks": "Actualiza tus favoritos: <b>ozimut.com</b>.",
  "moved.push": "Hay que volver a autorizar las notificaciones en este dispositivo, en <a href=\"#/reglages\">Ajustes</a>.",
  "moved.home": "En iPhone o iPad, si el sitio estaba en tu pantalla de inicio: quita el icono antiguo y añade ozimut.com desde Safari (Compartir › Añadir a pantalla de inicio).",
  "moved.ia": "Si habías guardado una clave de API para «IA», tienes que volver a introducirla.",
  "moved.method": "El método «Top» se llama ahora método Ozimut: tu CN Top se ha convertido en tu índice Ozimut.",
  "moved.mail": "Los correos del sitio llegan ahora desde alert@ozimut.com; para escribirnos: contact@ozimut.com.",
  "moved.ok": "Entendido",
  "bridge.waiting.one": "O'CN pasa a ser Ozimut, en ozimut.com. Este navegador aún guarda un envío del trazado que espera a la red: abre «Trazado» con conexión para que se envíe y luego recarga la página para pasar a ozimut.com.",
  "bridge.waiting.other": "O'CN pasa a ser Ozimut, en ozimut.com. Este navegador aún guarda {n} envíos del trazado que esperan a la red: abre «Trazado» con conexión para que se envíen y luego recarga la página para pasar a ozimut.com.",
