  "rl.model": "El modelo: en una posta, un corredor para el que {cnThe} vale c tarda k × tiempo de referencia ÷ c; k se fija para que el mejor equipo de todos los clubes (en el CNE, la media de los 5 mejores) sume la suma de los tiempos de referencia, como exige la FFCO. El mejor equipo se calcula de forma exacta, incluidos los criterios de composición y las postas reservadas (reglamento de competiciones 2026). La edad y el sexo vienen de la categoría del corredor: un veterano que corre en M21 cuenta como M21.",
  "cfc.title": "Copa de Francia de clubes (recalculada)",
  "cfc.hint": "La clasificación nacional de clubes de la FFCO, recalculada temporada a temporada con la regla de 2026; haz clic en una temporada para ver su clasificación",
  "cfc.rule": "Regla (reglamento de competiciones 2026, anexo 2): cada corredor aporta a su club la suma de sus 5 mejores puntuaciones del CN oficial del año a pie (bosque y sprint), más sus 5 mejores en MTB-O o Ski-O; los puntos de una mujer se multiplican por 1,4. Cálculo de Ozimut, no oficial: cuentan todos los corredores clasificados (no se conoce el tipo de licencia), y un corredor que cambió de club durante el año cuenta para el club de su última carrera. * La copa no se otorgó de 2023 a 2025.",
