  "spl.pace": "Ritmo habitual",
  "spl.reg": "Irregularidad",
  "spl.kmPace": "Min/km",
  "spl.sum.def": "Tramos ganados: los mejores tiempos. Posición media: en los tramos. Parte perdida: el tiempo perdido en relación con el tiempo de carrera. Ritmo habitual: la diferencia con el mejor tiempo en los tramos corridos sin error (el tiempo del corredor en relación con la suma de los mejores tiempos). Irregularidad: la dispersión de las diferencias con el mejor (coeficiente de variación); cuanto más baja, más regular la carrera. Duelos ganados: los corredores del recorrido batidos en más tramos de los que ganaron.",
  "prov.seeSplits": "Ver",
  "spl.def": "Tiempo perdido: en cada tramo, la diferencia entre el tiempo del corredor y su tiempo «ideal»: el tiempo de referencia del tramo (la media del sexto más rápido, sin el ganador; con menos de 12 tiempos, la media de los dos mejores; con menos de 5, el mejor) multiplicado por su ritmo habitual, es decir, su tiempo en los tramos corridos sin error en relación con sus tiempos de referencia — un tramo largo cuenta más que uno corto. Es el tiempo perdido tal como lo calculan MeOS y WinSplits, en los que se inspiran la mayoría de las vistas de esta página.",
  "spl.tab.clock": "Pasos",
  "spl.tab.follow": "Autonomía",
  "spl.tab.regular": "Regularidad",
  "spl.start": "Salida",
  "spl.startAbbr": "S",
  "spl.finishAbbr": "M",
  "spl.table.marks": "Marco naranja: un tiempo que los controles de arriba consideran dudoso (pasa el ratón por la casilla).",
  "spl.table.followed": "Trazo de color a la izquierda: un tramo corrido detrás de otro corredor (ver «Autonomía»).",
  "spl.clk.all": "Todos los corredores",
  "spl.clk.sel": "Solo los corredores comparados",
  "spl.clk.title": "Gráfico de pasos",
  "spl.clk.hint": "Cada línea: un corredor, control tras control, a la hora de su paso. Líneas que se juntan: corredores juntos; una línea más inclinada: un corredor que alcanza a otros. Rueda del ratón para hacer zoom; elige los corredores en color bajo el gráfico",
  "spl.clk.def": "Las horas son las de los pasos: la hora de salida más el tiempo acumulado en cada control. Solo se dibujan los corredores cuya hora de salida se conoce ({n} de {of}).",
  "spl.clk.none": "No hay horas de salida para este recorrido: los pasos no se pueden situar en el tiempo (WinSplits, liveresultat y los archivos IOF XML las dan).",
  "spl.fol.thr": "Juntos a menos de",
  "spl.fol.t1": "Diferencia en segundos hasta la que dos corredores van totalmente juntos",
  "spl.fol.t2": "Diferencia en segundos a partir de la cual ya no van juntos",
  "spl.fol.t1u": "s, luego cada vez menos hasta",
  "spl.fol.t2u": "s",
  "spl.fol.title": "Autonomía: quién siguió a quién",
  "spl.fol.hint": "En cada tramo, dos corredores del recorrido que salieron del mismo control con menos de {t2} s de diferencia: juntos donde los separan menos de {t1} s, cada vez menos hasta {t2} s. El segundo en pasar sigue al primero. Haz clic en un encabezado para ordenar",
  "spl.fol.def": "Índice de seguidor: el tiempo corrido detrás de otro corredor menos el tiempo corrido delante, en relación con el tiempo de los tramos contados (positivo: más bien seguidor; negativo: más bien liebre). Entre dos controles se supone que cada uno avanza a velocidad constante: es una estimación, y un corredor cercano en el tiempo no tiene por qué ser seguido (puede haber elegido otra ruta). Hacen falta las horas de salida; solo cuentan los tramos cuyos dos tiempos se conocen. Un tramo es «detrás» o «delante» si lo es durante más de la mitad de su tiempo.",
  "spl.fol.none": "No hay horas de salida para este recorrido (o hay un solo corredor): no se puede saber quién corría con quién.",
  "spl.fol.index": "Índice de seguidor",
  "spl.fol.index.hint": "Tiempo detrás menos tiempo delante, como parte del tiempo de carrera",
  "spl.fol.behindT": "Detrás",
  "spl.fol.aheadT": "Delante",
  "spl.fol.legsBehind": "Tramos detrás",
  "spl.fol.legsAhead": "Tramos delante",
  "spl.fol.main": "Compañero principal",
  "spl.fol.wasBehind": "detrás {t}",
  "spl.fol.wasAhead": "delante {t}",
  "spl.fol.cell": "Corrido detrás de {who}",
  "spl.reg.chart": "Dispersión en cada tramo",
  "spl.reg.chartHint": "Cuánto se alejaron los corredores de su propio nivel en este tramo, en puntos: las barras más altas son los tramos donde cada uno corrió de forma distinta a la habitual",
  "spl.reg.title": "Regularidad de los corredores",
  "spl.reg.hint": "Sobre {n} de los {of} corredores: los que terminaron con todos sus tiempos parciales. Haz clic en un encabezado para ordenar",
  "spl.reg.def": "Índice de rendimiento de un tramo: su tiempo de referencia (la media del mejor cuarto de los tiempos) dividido por el tiempo del corredor; 100 %: tan rápido como los mejores, 50 %: el doble de lento. Irregularidad: la desviación típica de esos índices, con cada tramo ponderado por su tiempo de referencia (un tramo largo dice más que uno corto), en relación con el índice medio del corredor (10 puntos de diferencia pesan más para quien corre al 40 % que para quien corre al 90 %); cuanto más baja, más regular la carrera. La dispersión de un tramo es la de los índices de los corredores en relación con su propia media: dejando aparte el nivel de cada uno, muestra dónde varió todo el mundo.",
  "spl.reg.none": "Nadie terminó este recorrido con todos sus tiempos parciales: no se puede calcular la regularidad.",
  "spl.reg.spread": "Dispersión",
  "spl.reg.pts": "puntos",
