  "ad.an.lede": "A petición (no aparecer más, representante legal de un menor, supresión de los datos de resultados), el nombre y el número de licencia de un federado se sustituyen, en todo el sitio publicado, por «Corredor anónimo N». Sus resultados siguen contando: los puestos, los valores de los recorridos y los CN e índices de los demás corredores no cambian. Se aplica en la próxima actualización del sitio, en menos de una hora; reversible.",
