  "nav.vma": "VAM",
  "nav.ask": "IA",
  "vma.lede": "Medir tu velocidad aeróbica máxima (VAM): los tests, una calculadora precisa para el medio Cooper y el Cooper en pista, tus ritmos de entrenamiento y las aplicaciones gratuitas para un test en pista.",
  "vma.tab.calc": "Calculadora",
