  "g.again": "Jugar otra vez",
  "g.rules": "Las reglas",
  "g.lvl.easy": "Fácil",
  "g.lvl.medium": "Medio",
  "g.lvl.hard": "Difícil",
  "g.lvl.small": "Pequeño",
