  "ia.ex.1": "¿Qué corredores de mi club están en el mejor percentil de su categoría en bosque? Haz una tabla.",
  "ia.ex.2": "Dibuja la diferencia entre mi CN oficial y mi índice Ozimut en los últimos 3 años.",
