  "ia.data": "Los datos",
  "ia.lede": "Haz una pregunta sobre las clasificaciones, los resultados o los clubes: una IA escribe la consulta, tu navegador la ejecuta sobre los datos del sitio y la convierte en una tabla o un gráfico.",
  "ia.placeholder": "Por ejemplo: mi índice Ozimut en bosque mes a mes desde 2024",
