  "cd.source": "Símbolos y textos: Purple Pen, según la especificación internacional de descripciones de control de la IOF. Dibujos del mapa: Ozimut, esquemáticos y sin escala, con los colores y símbolos de las normas ISOM 2017-2 e ISSprOM 2019-2.",
