  "sh.mine.tip": "Eres su organizador: gestiónala en el módulo Orga.",
  "cty.need.guest": "Sin cuenta, Stats muestra el corredor, la clasificación y las carreras del periodo que la federación publica libremente. Crea una cuenta y únete a Francia para verlo todo.",
  "tour.mod.try": "Probar {mod} sin cuenta",
  "tour.mod.orga.cta": "Crear una cuenta para organizar",
  "tour.mod.arena.title": "Toda la carrera, antes, durante y después",
  "tour.mod.arena.lede": "Arena reúne cada competición en un mismo lugar: el calendario y sus inscripciones, los horarios de salida en cuanto salen, el directo control a control, y luego los resultados de los organizadores, a menudo esa misma noche, con el análisis completo de los tiempos parciales. Elige una carrera, Arena hace el resto.",
  "tour.mod.stats.title": "La clasificación, por fin legible",
  "tour.mod.stats.lede": "Stats pone toda la orientación en cifras: tu índice y tu puesto, el detalle exacto de cada cálculo, tus progresos temporada tras temporada con un índice comparable de un año a otro desde 2010, los clubes, los relevos y las tendencias del país. Compárate, sigue a tus rivales, entiende cada punto ganado o perdido.",
  "tour.mod.coach.title": "Progresar entre dos carreras",
  "tour.mod.coach.lede": "Coach convierte tus tracks en lecciones: revive tu carrera sobre tu mapa, mira dónde se escapan los segundos, compara tus elecciones de ruta con las de los demás. Repasa las descripciones de control, entrena tu lectura de mapa con doce juegos y calcula tu VAM.",
  "tour.mod.coach.lede.lim": "Coach convierte tus tracks en lecciones: revive tu carrera sobre tu mapa, mira dónde se escapan los segundos, compara tus elecciones de ruta con las de los demás. Entrena tu lectura de mapa con doce juegos y calcula tu VAM.",
  "tour.mod.orga.title": "Organizar sin agotarse",
  "tour.mod.orga.lede": "Orga da a los clubes las herramientas del día de la prueba y de después: trazar los recorridos en el navegador, publicar horarios y resultados, emitir en directo desde MeOS, verificar los tiempos y ofrecer a los corredores su análisis de grupo. Se activa al registrarte o en tus ajustes, en un ordenador.",
  "tour.feat.eyebrow": "Precios",
  "tour.feat.title": "Todo es gratis, módulo a módulo",
  "tour.feat.lede": "Cada fila suma a la anterior. Sin cuenta, Ozimut muestra lo que es público; una cuenta abre las alertas y la opción de compartir tracks, y el módulo Orga las herramientas de los organizadores. Lo marcado con un asterisco exige además ser federado.",
  "tour.feat.note": "Reservado a los federados: en Francia, una cuenta que se ha unido a Francia, con su número de licencia FFCO verificado según el nombre. Los países cuyos resultados son todos públicos (España) están abiertos a todos.",
  "tour.feat.star": "Federados",
