  "tour.lvl.free": "Gratis para todos",
  "tour.method.long": "Tu nivel a lo largo del tiempo",
  "tour.method.long.1.b": "Quince temporadas, una sola regla.",
  "tour.method.long.1": "El índice Ozimut se recalcula desde 2010 con las mismas reglas, bosque, sprint, MTB-O y Ski-O cada uno por separado: tu curva se lee de principio a fin, sin ruptura el día en que cambia una regla oficial.",
  "tour.method.long.2.b": "Una misma escala, mes a mes.",
  "tour.method.long.2": "Cada mes el índice se reescala para que el 20 % mejor del país se mantenga en 5600 de media, sin saltos al cambiar de temporada: un índice de 2014 se compara con el de hoy.",
  "tour.method.long.3.b": "Cada carrera puntuada de una vez por todas.",
  "tour.method.long.3": "La puntuación de una carrera ya no cambia tras su publicación: tu historial no se mueve, y tu progresión se compara con la de tu categoría de edad.",
  "tour.multi.eyebrow": "Análisis de grupo",
  "tour.multi.title": "Todos los tracks en el mismo mapa",
  "tour.multi.lede": "El organizador prepara el mapa y el recorrido; cada uno añade su track. Salida en masa o desde un control, las rutas una junto a otra, las variantes agrupadas, las diferencias control a control y el cara a cara: todo para analizar un entrenamiento de club como una competición.",
  "tour.cap.multi.b": "La reproducción:",
  "tour.cap.multi": "cada corredor en el mismo mapa, en salida en masa, con su ritmo bajo el mapa.",
  "tour.cap.multi-gaps.b": "Las diferencias:",
  "tour.cap.multi-gaps": "el retraso de cada uno respecto al mejor, control tras control; un clic en un punto lleva la reproducción a ese paso.",
