  "ms.sp.intro": "El sprint se corre en ciudades y parques, a escala 1:4000 o 1:3000: sus símbolos son más grandes y su principio es sencillo: una línea negra gruesa nunca se cruza. Los símbolos marcados «sprint» no existen en un mapa de bosque.",
